<script setup lang="ts">
definePageMeta({layout:'workspace'})
type Member={user_id:string;role:string;profiles:{display_name:string|null}|null}
type Invitation={id:string;email:string;expires_at:string;accepted_at:string|null;revoked_at:string|null;created_at:string}
const db=useSupabaseClient(),{schoolId,schoolRole,platformAdmin}=useSchool()
const membershipAdmin=ref(false)
const canManage=computed(()=>platformAdmin.value||schoolRole.value==='school_admin'||membershipAdmin.value)
type Scope={id:string;name:string;permissions:string[]}
const permissionGroups=[["Students",["students.view","students.create","students.edit"]],["Houses",["houses.view","houses.create","houses.edit"]],["Staff",["staff.view"]],["Competitions",["competitions.view","competitions.create","competitions.edit","competitions.manage"]],["Registrations",["registrations.view","registrations.create","registrations.edit"]],["Race day",["race_day.view","race_day.manage","race_day.enter_results"]],["Results",["results.view","results.edit","results.publish"]],["Records & reports",["records.view","records.export","records.manage"]],["School settings",["school_settings.manage"]]]
const selectedPermissions=computed(()=>{if(!selected.value)return new Set<string>();if(platformAdmin.value&&selected.value.user_id===currentUserId.value||selected.value.role==='school_admin')return new Set(permissionGroups.flatMap(([,items])=>items));return new Set(scopes.value.filter(s=>assignments.value.some(a=>a.user_id===selected.value?.user_id&&a.scope_id===s.id)).flatMap(s=>s.permissions||[]))})
const currentUserId=ref('')
const scopes=ref<Scope[]>([]),assignments=ref<{user_id:string;scope_id:string}[]>([])
const accessRole=ref('teacher'),promotionRequests=ref<{id:string;school_id:string;user_id:string;status:string}[]>([]),requesting=ref(false)
const editing=ref(false),confirmSave=ref(false),saving=ref(false),editRole=ref('teacher'),editScopes=ref<string[]>([])
const members=ref<Member[]>([]),invitations=ref<Invitation[]>([])
const activeTab=ref('directory')
const inviteEmail=ref(''),inviteBusy=ref(false),inviteMessage=ref('')
async function sendInvitation(){if(!canManage.value||inviteBusy.value)return;inviteBusy.value=true;error.value='';inviteMessage.value='';try{const {data:{session}}=await db.auth.getSession();if(!session?.access_token)throw new Error('Please sign in again');const result=await $fetch<{message:string}>('/api/staff/invite',{method:'POST',headers:{Authorization:'Bearer '+session.access_token},body:{school_id:schoolId.value,email:inviteEmail.value}});inviteMessage.value=result.message;inviteEmail.value='';await load()}catch(e:any){error.value=e?.data?.message||e?.message||'Invitation could not be sent'}finally{inviteBusy.value=false}}
async function revokeInvitation(id:string){if(!canManage.value||inviteBusy.value||!confirm('Revoke this staff invitation?'))return;inviteBusy.value=true;error.value='';try{const r=await db.rpc('cancel_school_staff_invitation',{p_school_id:schoolId.value,p_invitation_id:id});if(r.error)throw r.error;notice.value='Invitation revoked';await load()}catch(e:any){error.value=e?.message||'Unable to revoke invitation'}finally{inviteBusy.value=false}}
const loading=ref(false),notice=ref(''),error=ref(''),search=ref(''),filter=ref('all'),selected=ref<Member|null>(null),open=ref(false)
const filtered=computed(()=>members.value.filter(m=>(filter.value==='all'||m.role===filter.value)&&(m.profiles?.display_name||m.user_id).toLowerCase().includes(search.value.trim().toLowerCase())))
const admins=computed(()=>members.value.filter(m=>m.role==='school_admin').length)
const canEditSelected=computed(()=>canManage.value&&!!selected.value&&(platformAdmin.value||selected.value.user_id!==currentUserId.value))
const teachers=computed(()=>members.value.filter(m=>m.role==='teacher').length)
const inviteStatus=(i:Invitation)=>i.revoked_at?'Revoked':i.accepted_at?'Accepted':new Date(i.expires_at).getTime()<Date.now()?'Expired':'Pending'
async function load(){if(!schoolId.value){membershipAdmin.value=false;members.value=[];invitations.value=[];return}loading.value=true;error.value='';try{
const {data:{user:viewer}}=await db.auth.getUser();currentUserId.value=viewer?.id||''
const m=await db.from('school_memberships').select('user_id,role').eq('school_id',schoolId.value)
if(m.error)throw m.error;const raw=(m.data||[]) as {user_id:string;role:string}[];const ids=raw.map(x=>x.user_id);const p=ids.length?await db.from('profiles').select('id,display_name').in('id',ids):{data:[],error:null};if(p.error)throw p.error;membershipAdmin.value=raw.some(x=>x.user_id===currentUserId.value&&x.role==='school_admin');const names=new Map((p.data||[]).map(x=>[x.id,x.display_name]));members.value=raw.map(x=>({...x,profiles:{display_name:names.get(x.user_id)||null}}))
if(canManage.value){const [s,a]=await Promise.all([db.from('school_access_scopes').select('id,name,permissions').eq('school_id',schoolId.value).order('name'),db.from('school_staff_scope_assignments').select('user_id,scope_id').eq('school_id',schoolId.value)]);if(s.error||a.error)throw s.error||a.error;scopes.value=(s.data||[]) as Scope[];assignments.value=(a.data||[]) as {user_id:string;scope_id:string}[]
const i=await db.from('school_staff_invitations').select('id,email,expires_at,accepted_at,revoked_at,created_at').eq('school_id',schoolId.value).order('created_at',{ascending:false});if(i.error)throw i.error;invitations.value=(i.data||[]) as Invitation[];const promotion=await db.from('school_admin_promotion_requests').select('id,school_id,user_id,status').eq('school_id',schoolId.value).eq('status','pending');promotionRequests.value=(promotion.data||[]) as {id:string;school_id:string;user_id:string;status:string}[]}else{invitations.value=[];scopes.value=[];assignments.value=[];promotionRequests.value=[]}
}catch(e:any){error.value=e.message||'Unable to load staff'}finally{loading.value=false}}
function view(member:Member){selected.value=member;editing.value=false;confirmSave.value=false;editRole.value=member.role;editScopes.value=assignments.value.filter(a=>a.user_id===member.user_id).map(a=>a.scope_id);accessRole.value=member.role==='school_admin'?'school_admin':editScopes.value[0]?'scope:'+editScopes.value[0]:'teacher';open.value=true}
function toggleScope(id:string,checked:boolean){editScopes.value=checked?[...editScopes.value,id]:editScopes.value.filter(s=>s!==id)}
async function saveStaff(){if(!canEditSelected.value||!selected.value||saving.value)return;saving.value=true;error.value='';try{
const userId=selected.value.user_id
const role=accessRole.value==='school_admin'?'school_admin':accessRole.value.startsWith('scope:')?'scope':'teacher'
const scope=role==='scope'?accessRole.value.slice(6):null
const result=await db.rpc('set_staff_access_role',{p_school:schoolId.value,p_user:userId,p_role:role,p_scope:scope});if(result.error)throw result.error
await load();selected.value=members.value.find(m=>m.user_id===userId)||null;editScopes.value=assignments.value.filter(a=>a.user_id===userId).map(a=>a.scope_id);editing.value=false;confirmSave.value=false;notice.value='Staff permissions updated'
}catch(e:any){error.value=e.message||'Unable to update staff';confirmSave.value=false}finally{saving.value=false}}
async function requestPromotion(){if(!selected.value||requesting.value)return;requesting.value=true;error.value='';try{const r=await db.rpc('request_school_admin_promotion',{p_school_id:schoolId.value,p_user_id:selected.value.user_id});if(r.error)throw r.error;notice.value='School Administrator promotion requested';await load()}catch(e:any){error.value=e.message||'Unable to request promotion'}finally{requesting.value=false}}
async function decidePromotion(id:string,approve:boolean){if(!platformAdmin.value||requesting.value)return;requesting.value=true;error.value='';try{const r=await db.rpc('decide_school_admin_promotion',{p_request_id:id,p_approve:approve});if(r.error)throw r.error;notice.value=approve?'Promotion approved':'Promotion rejected';await load()}catch(e:any){error.value=e.message||'Unable to decide request'}finally{requesting.value=false}}
watch([schoolId,schoolRole,platformAdmin],()=>{open.value=false;membershipAdmin.value=false;void load()},{immediate:true})
</script>
<template><div class="space-y-6">
<div class="flex flex-wrap items-stretch justify-end gap-2"><div v-for="m in [{label:'Total staff',value:members.length},{label:'Administrators',value:admins},{label:'Teachers',value:teachers}]" :key="m.label" class="flex min-w-[125px] flex-1 items-center justify-between gap-3 rounded-xl border border-[var(--border)] bg-[var(--panel)] px-4 py-3 sm:max-w-[200px]"><span class="text-xs text-[var(--muted)]">{{m.label}}</span><strong class="text-xl">{{m.value}}</strong></div></div>
<p v-if="notice" role="status" class="text-sm text-green-700">{{notice}}</p><p v-if="error" role="alert" class="rounded-xl bg-red-50 p-4 text-red-700">{{error}}</p>
<nav aria-label="Staff sections" class="flex flex-wrap gap-2 border-b border-[var(--border)] pb-3"><button v-for="tab in [{id:'directory',label:'Staff directory'},{id:'invitations',label:'Invitations'},{id:'promotions',label:'Admin promotions'}].filter(t=>t.id==='directory'||(t.id==='promotions'?platformAdmin:canManage))" :key="tab.id" type="button" :aria-current="activeTab===tab.id?'page':undefined" :class="activeTab===tab.id?'bg-blue-600 text-white':'bg-[var(--panel)] text-[var(--ink)]'" class="rounded-xl border border-[var(--border)] px-4 py-3 text-sm font-semibold" @click="activeTab=tab.id">{{tab.label}}<span v-if="tab.id==='promotions'&&promotionRequests.length" class="ml-2">({{promotionRequests.length}})</span></button></nav>
<UiPanel v-if="activeTab==='directory'"><div class="mb-5 flex flex-wrap items-center justify-between gap-3"><h2 class="text-lg font-bold">Staff directory</h2><button class="rounded-xl border border-[var(--border)] px-4 py-2 text-sm" :disabled="loading" @click="load">Refresh</button></div><div class="mb-5 flex flex-wrap gap-3"><input v-model="search" aria-label="Search staff" placeholder="Search staff" class="min-w-[200px] flex-1 rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"/><select v-model="filter" aria-label="Filter staff role" class="rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"><option value="all">All roles</option><option value="school_admin">School administrators</option><option value="teacher">Teachers</option></select></div><p v-if="loading" class="py-6">Loading staff…</p><div v-else class="overflow-x-auto"><table class="w-full min-w-[430px] text-left text-sm"><thead><tr class="border-b border-[var(--border)] text-[var(--muted)]"><th class="py-3">Staff member</th><th class="p-3">Role</th><th class="p-3">Action</th></tr></thead><tbody><tr v-for="m in filtered" :key="m.user_id" class="border-b border-[var(--border)]"><td class="py-4 font-semibold">{{m.profiles?.display_name||'Name not provided'}}</td><td class="p-3">{{m.role==='school_admin'?'School administrator':m.role==='teacher'?'Teacher':m.role}}</td><td class="p-3"><button type="button" :aria-label="'View '+(m.profiles?.display_name||'staff member')" class="rounded-lg border border-[var(--border)] p-2 text-blue-600" @click="view(m)"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="2" width="18" height="20" rx="2"/><circle cx="12" cy="10" r="3"/><path d="M7 18a5 5 0 0 1 10 0"/></svg></button></td></tr></tbody></table><p v-if="!filtered.length" class="py-8 text-center text-[var(--muted)]">No matching staff.</p></div></UiPanel>
<UiPanel v-if="canManage&&activeTab==='invitations'"><h2 class="mb-3 text-lg font-bold">Staff invitations</h2><form class="mb-5 flex flex-wrap items-end gap-3" @submit.prevent="sendInvitation"><label class="min-w-[240px] flex-1 text-sm font-semibold">Staff email address<input v-model="inviteEmail" required type="email" maxlength="254" placeholder="name@school.edu.au" class="mt-2 w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"/></label><button :disabled="inviteBusy" class="rounded-xl bg-blue-600 px-5 py-3 font-semibold text-white">{{inviteBusy?'Sending…':'Send invitation'}}</button></form><p class="mb-4 text-sm text-[var(--muted)]">Invitations are emailed through Microsoft Graph, expire after seven days and initially grant Teacher access. You can assign a custom Access Role after acceptance.</p><p v-if="inviteMessage" role="status" class="mb-4 text-sm text-green-700">{{inviteMessage}}</p><UiHoverScrollbar max-height="18rem"><div v-for="i in invitations" :key="i.id" class="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--border)] py-3 text-sm"><span>{{i.email}}</span><div class="flex items-center gap-2"><span class="rounded-lg bg-[var(--surface)] px-3 py-1">{{inviteStatus(i)}}</span><button v-if="inviteStatus(i)==='Pending'" class="rounded-lg border border-[var(--border)] px-3 py-2" :disabled="inviteBusy" @click="revokeInvitation(i.id)">Revoke</button></div></div><p v-if="!invitations.length" class="py-4 text-sm text-[var(--muted)]">No staff invitations.</p></UiHoverScrollbar></UiPanel>
<UiPanel v-if="platformAdmin&&activeTab==='promotions'"><h2 class="mb-3 text-lg font-bold">Pending School Administrator promotions</h2><div v-for="r in promotionRequests" :key="r.id" class="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--border)] py-3"><span>{{members.find(m=>m.user_id===r.user_id)?.profiles?.display_name||r.user_id}}</span><div class="flex gap-2"><button class="rounded-lg bg-blue-600 px-3 py-2 text-white" :disabled="requesting" @click="decidePromotion(r.id,true)">Approve</button><button class="rounded-lg border border-[var(--border)] px-3 py-2" :disabled="requesting" @click="decidePromotion(r.id,false)">Reject</button></div></div></UiPanel>
<div v-if="open&&selected" class="fixed inset-0 z-50 grid place-items-center bg-black/60 p-4" @click.self="open=false"><section role="dialog" aria-modal="true" aria-label="Staff details" class="w-full max-w-2xl rounded-2xl bg-[var(--surface)] p-6 text-[var(--ink)] shadow-xl"><UiHoverScrollbar max-height="calc(90vh - 48px)"><header class="mb-5 flex items-center justify-between"><h2 class="text-xl font-bold">{{editing?'Edit staff':'Staff details'}}</h2><div class="flex items-center gap-3"><button v-if="canEditSelected&&!editing" aria-label="Edit staff" title="Edit staff" class="rounded-lg border border-[var(--border)] p-2 text-blue-600" @click="editing=true">✎</button><button aria-label="Close" @click="open=false" class="text-[#991B1B]"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5"/><path d="M21 12H9"/></svg></button></div></header>
<div class="space-y-3"><div class="rounded-xl bg-[var(--panel)] p-4"><p class="text-xs text-[var(--muted)]">Name</p><strong>{{selected.profiles?.display_name||'Name not provided'}}</strong></div><div class="rounded-xl bg-[var(--panel)] p-4"><p class="mb-2 text-xs text-[var(--muted)]">Access role</p><select v-if="editing" v-model="accessRole" class="w-full cursor-pointer rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3" aria-label="Staff access role"><option value="teacher">Teacher</option><option v-if="platformAdmin" value="school_admin">School Administrator</option><option v-for="scope in scopes" :key="scope.id" :value="'scope:'+scope.id">{{scope.name}}</option></select><strong v-else>{{selected.role==='school_admin'?'School Administrator':editScopes.length?scopes.filter(s=>editScopes.includes(s.id)).map(s=>s.name).join(', '):'Teacher'}}</strong><div v-if="!editing&&canManage&&!platformAdmin&&selected.role!=='school_admin'" class="mt-3"><button class="rounded-lg border border-[var(--border)] px-3 py-2 text-sm text-blue-600" :disabled="requesting||promotionRequests.some(r=>r.user_id===selected?.user_id)" @click="requestPromotion">{{promotionRequests.some(r=>r.user_id===selected?.user_id)?'Promotion requested':'Request School Admin Access'}}</button></div></div>
<div class="rounded-xl bg-[var(--panel)] p-4"><p class="mb-3 text-xs text-[var(--muted)]">Custom access scopes</p><div v-if="editing" class="hidden"><label v-for="scope in scopes" :key="scope.id" class="flex items-center gap-2 text-sm"><input type="checkbox" :checked="editScopes.includes(scope.id)" @change="toggleScope(scope.id,($event.target as HTMLInputElement).checked)"/>{{scope.name}}</label><p v-if="!scopes.length" class="text-sm text-[var(--muted)]">No custom scopes yet. Create them under Access Scopes.</p></div><div v-else class="text-sm">{{assignments.filter(a=>a.user_id===selected?.user_id).map(a=>scopes.find(s=>s.id===a.scope_id)?.name).filter(Boolean).join(', ')||'No custom scopes assigned'}}</div></div></div>
<div v-if="!editing" class="mt-4 rounded-xl bg-[var(--panel)] p-4"><div class="mb-3 flex flex-wrap items-center justify-between gap-2"><h3 class="font-semibold">Effective permissions</h3><span class="text-xs text-[var(--muted)]">Read-only</span></div><p class="mb-3 text-xs text-[var(--muted)]">Green ticks show permissions granted by the staff member’s role or assigned access scopes. Red crosses show permissions not granted.</p><div v-for="[category,permissions] in permissionGroups" :key="category" class="mt-4"><h4 class="mb-2 font-semibold">{{category}}</h4><div class="grid gap-2 sm:grid-cols-2"><div v-for="permission in permissions" :key="permission" class="flex items-center gap-2 rounded-lg border border-[var(--border)] bg-[var(--surface)] px-3 py-2 text-sm"><svg v-if="selectedPermissions.has(permission)" class="shrink-0 text-green-600" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-label="Allowed" role="img"><path d="m5 12 4 4L19 6"/></svg><svg v-else class="shrink-0 text-red-600" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-label="Not allowed" role="img"><path d="M18 6 6 18M6 6l12 12"/></svg><span>{{permission.split('.').slice(1).join(' ').replaceAll('_',' ')}}</span></div></div></div></div>
<div class="mt-5 flex justify-end gap-3"><button class="rounded-xl border border-[var(--border)] px-5 py-3" @click="editing?editing=false:open=false">{{editing?'Cancel':'Close'}}</button><button v-if="editing" class="rounded-xl bg-blue-600 px-5 py-3 font-semibold text-white inline-flex items-center gap-2" :disabled="saving" @click="confirmSave=true"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2Z"/><path d="M17 21v-8H7v8M7 3v5h8"/></svg><span>Save changes</span></button></div></UiHoverScrollbar></section></div>
<div v-if="confirmSave" class="fixed inset-0 z-[60] grid place-items-center bg-black/70 p-4"><section role="alertdialog" aria-modal="true" class="w-full max-w-sm rounded-2xl bg-[var(--surface)] p-6 text-[var(--ink)] shadow-xl"><h3 class="text-lg font-bold">Save staff changes?</h3><p class="mt-3 text-sm">{{selected?.role==='school_admin'&&accessRole!=='school_admin'?'This will remove School Administrator access and replace it with the selected lower access role. Continue?':'Update the access role and permissions for this staff member?'}}</p><div class="mt-6 flex justify-end gap-3"><button class="rounded-xl border border-[var(--border)] px-4 py-2" @click="confirmSave=false">Cancel</button><button class="rounded-xl bg-blue-600 px-4 py-2 text-white" :disabled="saving" @click="saveStaff">Yes, save</button></div></section></div>
</div></template>